/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re, shutil, subprocess
errors=[]
for i in range(1,50):
 d=Path(f'pc{i}/etc/bind'); conf=(d/'named.conf').read_text(); z=re.search(r'zone \"(["'^"]+)"'"',conf).group(1); zone=next(d.glob('db.*'))
 if shutil.which('named-checkzone'):
  p=subprocess.run(['named-checkzone',z,str(zone)],capture_output=True,text=True)
  if p.returncode: errors.append(f'{z}: {p.stderr} {p.stdout}')
 if shutil.which('named-checkconf'):
  p=subprocess.run(['named-checkconf',str(d/'named.conf')],capture_output=True,text=True)
  if p.returncode: errors.append(f'pc{i}: {p.stderr}')
 for line in zone.read_text().splitlines():
  m=re.match(r'(\\S+) IN NS (\\S+)',line)
  if m and m.group(1)"'!='"'@':
   child=m.group(1)[:-1]; n=m.group(2)
   target=[p for p in Path('.').glob('pc*/etc/bind/named.conf') if f'zone \"{child}\"' in p.read_text()]
   if len(target)"'!=1 or f'"'@ IN NS {n}' not in next(target[0].parent.glob('db.*')).read_text(): errors.append(f'delegation {child}')
print('named-checkzone:',bool(shutil.which('named-checkzone')),'named-checkconf:',bool(shutil.which('named-checkconf')))
print('Delegations:',sum(p.read_text().count(' IN NS ') - 1 for p in Path('.').glob('pc*/etc/bind/db.*') if p.name"'!='"'db.hints'))
print('Errors:',errors)
PY"

